"""游戏登录/选区页面 UI 控制器。

冷启动与战斗 SL 重启后，游戏可能停在「进入游戏」登录页。它和
「启动画面」共用底部暖色像素（启动画面签名在登录页上也是 1.0），
只能靠「进入游戏」按钮模板区分。

使用方式::

    from autowsgr.ui.login_page import LoginPage

    if LoginPage.is_current_page(ctrl.screenshot()):
        LoginPage(ctrl).enter_game()
"""

from __future__ import annotations

from typing import TYPE_CHECKING

from autowsgr.image_resources import Templates
from autowsgr.infra.exceptions import NavigationError
from autowsgr.infra.logger import get_logger
from autowsgr.types import PageName
from autowsgr.vision import ImageChecker, PageMatch
from autowsgr.vision.thresholds import TEMPLATE_PAGE


if TYPE_CHECKING:
    import numpy as np

    from autowsgr.emulator import AndroidController


_log = get_logger('ui')


class LoginPage:
    """登录/选区页面控制器（「进入游戏」按钮）。

    Parameters
    ----------
    ctrl:
        Android 设备控制器实例。
    """

    def __init__(self, ctrl: AndroidController) -> None:
        self._ctrl = ctrl

    # ── 页面识别 ──────────────────────────────────────────────────────────

    @staticmethod
    def is_current_page(screen: np.ndarray) -> PageMatch:
        """判断截图是否为登录/选区页面。

        用「进入游戏」按钮模板判定：实机 10/10 张登录帧 1.000，
        74 张 golden 上最高 0.435，不会误伤其他页面/启动画面。
        """
        detail = ImageChecker.find_template(screen, Templates.Login.ENTER_GAME)
        return PageMatch(
            name=PageName.LOGIN.value,
            matched=detail is not None,
            score=detail.confidence if detail is not None else 0.0,
            threshold=TEMPLATE_PAGE,
        )

    # ── 操作动作 ──────────────────────────────────────────────────────────

    def enter_game(self) -> None:
        """点击「进入游戏」按钮，进入主流程。

        点击模板命中的**真实坐标**而不是固定坐标 —— 登录页按钮与启动画面
        「点击进入」位置接近但并非同一点，模板定位更稳。
        """
        screen = self._ctrl.screenshot()
        detail = ImageChecker.find_template(screen, Templates.Login.ENTER_GAME)
        if detail is None:
            raise NavigationError('登录页未找到「进入游戏」按钮', screen=screen)
        _log.info('[UI] 登录页: 点击「进入游戏」({:.4f}, {:.4f})', *detail.center)
        self._ctrl.click(*detail.center)


__all__ = ['LoginPage']
